3|/**
4| * MARK: reconcileInterruptedRuns
5| * @description Reconciles tasks stuck in a live running_* status with no
6| *   engine owner (e.g. after a server restart): transitions them to
7| *   'interrupted'. Covers every running variant the executors can leave
8| *   behind (running_agent/ci/merge, advancing) plus the legacy
9| *   `running_deploy` label kept so pre-migration task records still
10| *   reconcile; the disk-load path (parseTaskMarkdown) applies the same
11| *   rule, so both reads agree. The engine owner's live status is never
12| *   touched. Status-label-only and idempotent: a second pass finds
13| *   nothing to do.
14| * @example reconcileInterruptedRuns(store) => [{ projectId, taskId }]
15| ***/
16|export function reconcileInterruptedRuns(store) {
17|	const projects =
18|		store.projectStore && typeof store.projectStore.listProjects === "function"
19|			? store.projectStore.listProjects()
20|			: [];
21|	const reconciled = [];
22|
23|	for (const project of projects) {
24|		let tasks;
25|		try {
26|			tasks = store.listTasks(project.id, project.cwd);
27|		} catch {
28|			continue;
29|		}
30|		for (const task of tasks) {
31|			// Fail-safe: one unreadable or unpersistable task must never block
32|			// the rest of the pass — or boot, when called from startup
33|			// recovery. The failure is recorded in history and reconciliation
34|			// continues with the next task.
35|			try {
36|				if (
37|					ORPHANED_RUNNING_STATUSES.has(task?.status) &&
38|					store.engineState?.activeTaskId !== task.id
39|				) {
40|					task.status = "interrupted";
41|					task.wasInterrupted = true;
42|					task.updatedAt = new Date().toISOString();
43|					// Best-effort persistence: a store without markdown/history
44|					// helpers (tests, partial seams) still reconciles the
45|					// status — the flip is what recovery depends on.
46|					try {
47|						store._recordHistory?.(
48|							task,
49|							"Stage execution interrupted by server restart",
50|							task.updatedAt,
51|						);
52|					} catch {
53|						// History is best-effort; the flip already happened.
54|					}
55|					try {
56|						store._saveTaskMarkdown?.(project.cwd, task);
57|					} catch {
58|						// Persistence is best-effort; the flip already happened.
59|					}
60|					reconciled.push({ projectId: project.id, taskId: task.id });
61|				}
62|			} catch (taskError) {
63|				try {
64|					store._recordHistory?.(
65|						task,
66|						`Run reconciliation skipped: ${taskError?.message || taskError}`,
67|						new Date().toISOString(),
68|					);
69|				} catch {
70|					// History write is best-effort; reconciliation continues.
71|				}
72|			}
73|		}
74|	}
75|
76|	return reconciled;
77|}

